components.css:
.ds-button-primary{--forest:#142c28;--amber:#f5b544;--paper:#f8faf7;--muted:#52635d;
    display: inline-flex;
    align-items: center;
    justify-content: space-between;
    gap: 35px;
    background: var(--amber);
    color: var(--forest) !important;
    min-height: 56px;
    padding: 14px 24px;
    border-radius: 5px;
    font-size: .95rem;
    font-weight: 700;
    line-height: 1.4
font-family:'Instrument Sans',ui-sans-serif,system-ui,sans-serif;text-decoration:none;}.ds-button-primary span{font-size:1.3rem}.ds-button-primary:hover{
    background: #ffca6c
}.ds-button-primary:focus-visible{outline:3px solid #ca7800;outline-offset:6px}

.ds-button-small{--forest:#142c28;--amber:#f5b544;--paper:#f8faf7;--muted:#52635d;
    display: inline-flex;
    align-items: center;
    justify-content: space-between;
    gap: 35px;
    background: var(--amber);
    color: var(--forest) !important;
    min-height: 56px;
    padding: 14px 24px;
    border-radius: 5px;
    font-size: .95rem;
    font-weight: 700;
    line-height: 1.4
font-family:'Instrument Sans',ui-sans-serif,system-ui,sans-serif;text-decoration:none;
    min-height: 44px;
    font-size: .8rem;
    padding: 11px 17px;
    gap: 20px
}.ds-button-small span{font-size:1.3rem}.ds-button-small:hover{
    background: #ffca6c
}.ds-button-small:focus-visible{outline:3px solid #ca7800;outline-offset:6px}@media(max-width:640px){.ds-button-small{font-size:.72rem;padding:10px 12px;min-height:40px;gap:0}.ds-button-small span{display:none}}

.ds-button-dark{--forest:#142c28;--amber:#f5b544;--paper:#f8faf7;--muted:#52635d;
    display: inline-flex;
    align-items: center;
    justify-content: space-between;
    gap: 35px;
    background: var(--amber);
    color: var(--forest) !important;
    min-height: 56px;
    padding: 14px 24px;
    border-radius: 5px;
    font-size: .95rem;
    font-weight: 700;
    line-height: 1.4
font-family:'Instrument Sans',ui-sans-serif,system-ui,sans-serif;text-decoration:none;
    background: var(--forest);
    color: #fff !important;
    flex-shrink: 0
}.ds-button-dark span{font-size:1.3rem}.ds-button-dark:hover{
    background: #2a4d43
}.ds-button-dark:focus-visible{outline:3px solid #ca7800;outline-offset:6px}

.ds-text-link{--forest:#142c28;--amber:#f5b544;--paper:#f8faf7;--muted:#52635d;font-family:'Instrument Sans',ui-sans-serif,system-ui,sans-serif;color:var(--forest);text-decoration:none;
    display: inline-flex;
    gap: 35px;
    align-items: center;
    font-size: .9rem;
    font-weight: 700;
    border-bottom: 1px solid #96a59a;
    padding: 4px 0
}.ds-text-link:hover{
    color: #946000
}.ds-text-link:focus-visible{outline:3px solid #ca7800;outline-offset:6px}

.ds-main-nav{--forest:#142c28;--amber:#f5b544;--paper:#f8faf7;--muted:#52635d;font-family:'Instrument Sans',ui-sans-serif,system-ui,sans-serif;color:var(--forest);
    display: flex;
    gap: 30px;
    align-items: center;
    font-size: .85rem;
    font-weight: 600
}.ds-main-nav a{color:inherit;text-decoration:none;transition:background-color .2s,color .2s}.ds-main-nav a:hover{color:#946000}.ds-main-nav a:focus-visible{outline:3px solid #ca7800;outline-offset:6px}@media(max-width:1000px){.ds-main-nav{display:none}}

.ds-feature{--forest:#142c28;--amber:#f5b544;--paper:#f8faf7;--muted:#52635d;font-family:'Instrument Sans',ui-sans-serif,system-ui,sans-serif;background:#eaf0e8;color:var(--forest);line-height:1.65;border-top:1px solid #b8c8ba;border-bottom:1px solid #b8c8ba;
    padding: 34px 35px 35px 0
}.ds-feature svg{width:32px;height:32px;fill:none;stroke:currentColor;stroke-width:1.6;stroke-linecap:round;stroke-linejoin:round;margin-bottom:22px}.ds-feature h3{margin:0;
    margin: 0

    font-size: 1.25rem;
    line-height: 1.3;
    font-weight: 650
}.ds-feature p{margin-bottom:0;
    margin-top: 12px;
    color: var(--muted);
    font-size: .92rem;
    max-width: 30ch
}@media(max-width:1000px){.ds-feature{padding-right:20px}}@media(max-width:640px){.ds-feature{padding:26px 0;display:flex;gap:22px}.ds-feature svg{flex-shrink:0;margin:0}.ds-feature p{max-width:37ch}}

.ds-step{--forest:#142c28;--amber:#f5b544;--paper:#f8faf7;--muted:#52635d;font-family:'Instrument Sans',ui-sans-serif,system-ui,sans-serif;color:var(--forest);line-height:1.65;
    display: flex;
    gap: 22px;
    padding: 25px 0;
    border-bottom: 1px solid #d4dfd3
}.ds-step-number{
    color: #7b570f;
    background: #f6e6c5;
    width: 35px;
    height: 35px;
    border-radius: 50%;
    display: grid;
    place-items: center;
    flex-shrink: 0;
    font-size: .9rem;
    font-weight: 700
}.ds-step h3{margin:0;
    margin: 0

    font-size: 1.25rem;
    line-height: 1.3;
    font-weight: 650
}.ds-step p{margin-bottom:0;
    color: var(--muted);
    font-size: .92rem;
    margin-top: 8px
}@media(max-width:640px){.ds-step{padding:22px 0}}
